void get_timer_settings(struct k_itimer *timr, struct itimerspec64 *cur_setting) {
    ktime_t now = ktime_get();
    ktime_t expires = timr->it_real.function == NULL ? ktime_set(0, 0) : timr->it_real.expires;

    if (expires != 0 && ktime_after(expires, now)) {
        cur_setting->it_interval = timr->it_interval;
        cur_setting->it_value = ktime_to_timespec64(ktime_sub(expires, now));
    } else {
        if (timr->it_interval.tv64 == 0) {
            cur_setting->it_value.tv64 = 0;
        } else {
            cur_setting->it_value = timr->it_interval;
        }
        cur_setting->it_interval = timr->it_interval;
    }
}

void get_timer_settings(struct k_itimer *timr, struct itimerspec64 *cur_setting) {
    ktime_t now = ktime_get();
    ktime_t expires = timr->it_REAL.timer.function == NULL ? KTIME_MAX : timr->it_REAL.timer.expires;

    if (expires == KTIME_MAX || (expires <= now && !timr->it_sigev_notify)) {
        cur_setting->it_interval = timr->it_interval;
        cur_setting->it_value = (struct __kernel_timespec64){0, 0};
    } else {
        ktime_t remaining = ktime_sub(expires, now);
        cur_setting->it_interval = timr->it_interval;
        cur_setting->it_value = ktime_to_timespec64(remaining);
    }
}

void get_timer_settings(struct k_itimer *timr, struct itimerspec64 *cur_setting) {
    ktime_t now = ktime_get();
    ktime_t expires = timr->it_real.function == NULL ? timr->it_real.timer.expires : timr->it_real.interval;

    if (timr->it_real.function == NULL && now >= timr->it_real.expires) {
        cur_setting->it_value.tv_sec = 0;
        cur_setting->it_value.tv_nsec = 0;
    } else {
        cur_setting->it_value = ktime_to_timespec64(ktime_sub(timr->it_real.expires, now));
    }

    cur_setting->it_interval = ktime_to_timespec64(timr->it_real.interval);
}

void get_timer_settings(struct k_itimer *timr, struct itimerspec64 *cur_setting) {
    ktime_t expires;
    ktime_t now;

    now = ktime_get();

    if (timr->it_interval.tv64) {
        cur_setting->it_interval = timr->it_interval;
    } else {
        cur_setting->it_interval.tv64 = 0;
    }

    if (timr->it_overrun == 0 && timr->it_signal == 0) {
        if (timr->it_expires.tv64 <= now.tv64) {
            cur_setting->it_value.tv64 = 0;
        } else {
            cur_setting->it_value.tv64 = ktime_to_ns(ktime_sub(timr->it_expires, now));
        }
    } else {
        cur_setting->it_value.tv64 = timr->it_expires.tv64;
    }
}

void get_timer_settings(struct k_itimer *timr, struct itimerspec64 *cur_setting) {
    ktime_t expires;
    s64 now;

    expires = timr->it_expire;
    now = ktime_get();

    if (expires > now) {
        cur_setting->it_value.tv_nsec = expires - now;
        cur_setting->it_value.tv_sec = 0;
    } else {
        cur_setting->it_value.tv_nsec = 0;
        cur_setting->it_value.tv_sec = 0;
    }

    cur_setting->it_interval.tv_sec = timr->it_interval.tv_sec;
    cur_setting->it_interval.tv_nsec = timr->it_interval.tv_nsec;
}
